  linalg.generic {
    indexing_maps = [
      affine_map<(d0) -> (d0)>,
      affine_map<(d0) -> (d0)>,
      affine_map<(d0) -> (d0)>
    ],
    iterator_types = ["parallel"]
  } ins(%arg0, %arg1 : memref<1024xf32>, memref<1024xf32>)
    outs(%arg2 : memref<1024xf32>) {
  ^bb0(%in1: f32, %in2: f32, %out: f32):
